"""Build the offline, illustrated stock request manual from reviewed content."""
from pathlib import Path
import base64, html, json

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'docs/stock-requests/2026-09-29'
pages = []

def shot(name, caption, width=None):
    path = OUT / 'screenshots' / (name + '.png')
    data = base64.b64encode(path.read_bytes()).decode()
    style = f' style="max-width:{width}px"' if width else ''
    return f'<figure{style}><img src="data:image/png;base64,{data}" alt="{html.escape(caption, quote=True)}" tabindex="0" role="button" aria-label="Enlarge screenshot: {html.escape(caption, quote=True)}"><figcaption>{caption}</figcaption></figure>'

def note(title, text, kind='tip'):
    return f'<aside class="{kind}"><strong>{title}</strong><p>{text}</p></aside>'

def steps(*items):
    return '<ol class="steps">' + ''.join(f'<li>{item}</li>' for item in items) + '</ol>'

def table(headers, rows, cls=''):
    return f'<table class="{cls}"><thead><tr>'+''.join(f'<th>{v}</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{v}</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'

def page(key, section, title, role, content, extra=''):
    pages.append({'id':key,'section':section,'title':title,'role':role,'content':content,'extra':extra})

page('start','User manual','Stock requests','Sales + SCM', '''
<div class="cover-intro"><p class="eyebrow">MBBS · OPERATOR APP</p><h1>Stock requests</h1><p class="cover-subtitle">A practical guide for<br>Sales and SCM</p><p class="cover-description">Regular stock transfers and special vendor enquiries, from the first request to the saved order result.</p></div>
<div class="cover-routes"><article><span class="route-letter">R</span><h2>Regular stock</h2><p>Request existing inventory from another yard.</p><p><b>Pickup / Delivery:</b> approval → Sales SO → confirmed routing</p><p><b>Stocking:</b> SCM review → adjusted items → direct TO</p></article><article><span class="route-letter">S</span><h2>Special stock</h2><p>Ask SCM to source a customer’s special items.</p><p>Vendor check → customer decision → SO → PO → readiness and fulfillment</p></article></div>
<div class="cover-meta"><b>Current feature guide · 29 September 2026</b><p>English edition · Includes step-by-step instructions, screenshots and troubleshooting.</p></div>
''' + note('About the screenshots', 'Screens show the deployed application with fictional training customers, products, quantities and order references. They illustrate separate workflow states; they are not live orders. Buttons depend on your role and the request’s status.') + '<p class="small">In the HTML edition, click a screenshot to enlarge it. Use the contents links to jump to a task. The PDF is formatted for A4 printing.</p>', 'cover')

page('contents','Start here','Find the right workflow','Sales + SCM', '''
<p class="lead">The former direct-TO Pickup option is now <b>Stocking</b>. Regular <b>Pickup</b> uses pre-approval and a Sales SO.</p>
''' + table(['Need','Use','What happens next'],[
 ('Existing stock at another yard; delivery required','<b>Regular → Delivery</b>','Approval checks, then Sales links an SO and confirms a location change or TO.'),
 ('Existing stock for customer pickup','<b>Regular → Pickup</b>','Pre-approval → Sales SO → routing confirmation. No minimum lead time.'),
 ('Stock for the Sales yard; direct transfer needed','<b>Regular → Stocking</b>','SCM always reviews, adjusts items and creates the TO directly. No Sales SO.'),
 ('Vendor-sourced or specially specified products','<b>Special</b>','SCM checks the vendor, Sales records the customer’s decision, then SO/PO processing follows.')]) + '''
<h2>Contents</h2><div class="toc">{{TOC}}</div>
''' + '<p class="small"><b>SO</b> = Sales Order · <b>PO</b> = Purchase Order · <b>TO</b> = Transfer Order · <b>ETA</b> = expected availability date. <b>SCM</b> = Supply Chain Management.</p>')

page('navigation','Start here','Open requests and find your work','Sales + SCM', '''
<p class="lead">Open <b>Request Stock</b> from the Sales menu, or the stock request page in SCM. Switch between <b>Special</b> and <b>Regular</b>.</p>
''' + shot('01-navigation','Sales view: request-type tabs, alerts, filters, case list and selected case.') + steps(
 'Choose the tab and a queue or stage. Search and use the yard/vendor filters to narrow the list.',
 'Select a request card. Read the details, status and next available action on the right. Use <b>Refresh</b> when you need the latest state.',
 'Check the alert buttons at the top. Regular decisions and special workflow alerts are separate. In Special, <b>My requests</b> filters to your cases.') + note('Make the page easier to read', 'Special request details have <b>−</b>, <b>+</b> and <b>Reset</b> text-size controls. Your choice is remembered in this browser. The page also offers English and Chinese.'))

page('regular-create','Regular · Sales','Submit a regular stock request','Sales', steps(
 'Choose <b>Regular</b> and start a new request. Confirm <b>Your destination yard</b>; it must be a yard you are authorized to use.',
 'Enter the customer if known. Choose <b>Pickup</b>, <b>Delivery</b> or <b>Stocking</b>. Only <b>Delivery</b> shows and requires arrival date and time, in <b>Toronto time</b>; entries format automatically. Pickup and Stocking need neither field.',
 'Search the item, choose <b>Request from yard</b>, and enter the quantity. Use the available PLT/LYR/SEC/PCS conversions, or the sales-quantity field when provided.',
 'Use <b>Add another line</b> if needed, add any remarks, then select <b>Submit request</b>. Read the resulting review route.') + shot('02-regular-form','Example: 2 PLT × 100 SQFT = 200 SQFT requested from 3445 for destination 2967.',600) + note('Read availability in the correct unit', 'The yard cards show sales quantity and available package conversions. <b>Live − reserved</b> is the requestable amount. Approval does not itself commit stock; NetSuite commits it when the SO or TO is processed.') + '<p class="small">Before the first decision, use <b>Edit request</b> or <b>Cancel request</b> when available.</p>')

page('regular-rules','Regular · Approval','Understand automatic approval','Sales + SCM', '''
<p class="lead"><b>Pickup and Delivery</b> can receive automatic pre-approval. Stocking always requires SCM review.</p>
''' + steps('Stock request auto-approval is switched on.', 'For <b>Delivery</b>, expected arrival is at least the configured lead time after submission. <b>Pickup has no minimum lead time.</b>', 'Every item at each source yard has enough available stock to leave <b>at least its safety stock</b> after the requested quantity is shipped.') + table(['Available','Safety stock','Requested','After shipment','Stock test'],[
 ('1,000','800','200','800','Pass — equal to safety stock is allowed'),
 ('1,000','800','201','799','Manual review — short by 1')]) + '<p>Quantities on matching item/source lines are added together for this check. If the stock policy or evidence needed for automatic approval is unavailable, SCM reviews the request.</p>' + note('Stocking always goes to SCM', 'Choose <b>Stocking</b> for SCM’s direct TO workflow. Stocking always requires manual review, even with sufficient stock.') + '<h2>SCM settings</h2>' + shot('23-regular-settings','Smart SCM → Settings: the three regular stock approval controls.') + table(['Setting','Verified on 29 Sep 2026','Effect'],[
 ('Stock request auto-approval','On','Off sends Pickup and Delivery to SCM; Stocking is always manual.'),
 ('Lead time','12 hours','Delivery only. Pickup has no minimum lead time; Stocking is manual.'),
 ('Approval validity','15 minutes','Pickup and Delivery: the window starts when all items are reviewed.')]) + '<p class="small">Authorized SCM users can edit these values in <b>Smart SCM → Settings</b> and select <b>Save settings</b>. Use the values recorded on the request when reviewing older cases. The verified Delivery lead time is 12 hours; Pickup is exempt.</p>')

page('regular-safety','Regular · SCM','Review the reason and safety stock','SCM', '''
<p>Open a request from the manual-review queue. Read <b>Why SCM review is required</b> and the per-line stock evidence before choosing a decision.</p>
''' + shot('03-regular-scm','201 SQFT would leave 799 SQFT against an 800 SQFT safety requirement. The shortfall is visible on the line.',620) + '<p class="small"><b>Refresh stock evidence</b> updates the review before execution. Review the requested total across matching lines, not only the quantity shown on one line.</p>')

page('regular-decisions','Regular · SCM','Decide lines and manage replenishment','SCM', steps('Select the actionable lines you intend to decide. Check source yards, quantities and evidence. If you edit a line, select <b>Save line adjustment</b> before deciding it.', 'Choose one of the approval options below, or reject the selected/actionable lines. Enter a rejection reason; add an approval note when useful.', 'Finish decisions on all lines. Sales receives an alert for manual approval or rejection. Pickup / Delivery SO processing waits until all line decisions are complete.') + table(['Action','Result'],[
 ('<b>Approve · TO / location change</b>','Approved Pickup / Delivery items follow Sales SO routing and confirmation.'),
 ('<b>Approve · source replenishment PO</b>','Uses the same Pickup / Delivery SO route and adds priority replenishment for the corresponding item/source in Smart SCM.'),
 ('<b>Reject selected / Reject all actionable</b>','Rejected lines do not proceed. Rejecting every actionable line closes the request’s stock path.')]) + note('Stocking uses its own action', 'For Stocking, use <b>Convert to TO</b> to review and issue the transfer directly. See pages 11–13.') + '<h2>Priority replenishment</h2>' + shot('24-regular-priority','Smart SCM → PO / TO proposals: priority stock-request replenishment remains at the top.') + '<p>These loads carry forward into subsequent proposal runs, including for paused items, until SCM selects <b>Release</b>. Review the proposal’s quantity: replenishment follows the current inventory position and target, so it may differ from the original request quantity.</p>' + note('What Release means', 'Release ends the priority carry-forward. It does not cancel a PO that has already been created.'))

page('regular-location','Regular · Sales','Link an SO and confirm a location change','Sales', steps('For an approved <b>Pickup or Delivery</b> request, create and save the SO at <b>your Sales location</b>, with open, unfulfilled stock lines at that yard.', 'Enter its SO number and select <b>Review SO routing</b> before approval expires. If <b>Select SO line</b> appears, choose the correct matching line and review again.', 'Read the confirmation. If all SO stock items are covered by one source yard, the app proposes changing the SO location to that yard.', 'Confirm to apply the displayed change, or select <b>Cancel</b> to leave it unprocessed.') + shot('04-regular-so','An approved Pickup request prompts Sales to enter its SO number.') + shot('05-regular-location-dialog','Single-source example: confirm the SO location change from 2967 to 3445.',440) + note('PALLET and other accompanying lines', 'PALLET, discount, subtotal and delivery-fee lines do not count as requested stock when deciding the route. They do not force a TO. The location-change action includes the accompanying SO lines as applicable.'))

page('regular-transfer','Regular · Sales','When the app creates Transfer Orders','Sales + SCM', '''
<p class="lead">The app proposes TOs to the Sales yard when the approved stock has multiple source yards, or the SO includes other stock items beyond the approved request.</p>
''' + shot('06-regular-to-dialog','Multiple sources: review each source → destination route before confirming.',430) + table(['SO and request situation','Expected action'],[
 ('All SO stock items approved from 3445; Sales yard 2967','Change SO location to 3445.'),
 ('Approved items from 3445 and 150; Sales yard 2967','Create TOs from the source yards to 2967.'),
 ('Some SO stock is already at 2967; approved requested stock is from 3445','Transfer the approved requested stock to 2967.'),
 ('SO also contains PALLET, discount, subtotal or delivery fee','These companion lines alone do not change the stock-routing decision.')]) + '<h2>Two approved lines and one rejected line</h2><p>Wait for all three decisions. Only the approved quantities may use the request. If the SO still includes the third stock item, it remains outside this approval and the app uses the transfer route for the approved items. If the SO contains only the two approved stock items from one source, a location change may apply.</p>' + note('Exact quantities and one SO per request', 'The SO must match the approved stock quantities and units. For example, <b>760 EACH approved versus 912 EACH on the SO</b> is rejected with the item and quantity difference. Correct the SO or obtain a new approval for the intended quantity. An SO already used by another regular request cannot be reused.'))

page('regular-expiry','Regular · Follow-up','Wait, retry and read the saved result','Sales + SCM', '<div class="two-cols"><div>' + shot('04b-regular-busy','Busy state while the application waits for NetSuite.') + '</div><div><h2>While processing</h2><p>The busy dialog explains what is happening. Buttons are disabled to prevent duplicate actions. Wait for the result.</p><p>If an operation needs attention, reopen the same request and use its available retry action. An operation that already started can resume its saved work; do not create a second request to repeat it.</p></div></div>' + '<h2>Unused Pickup or Delivery approval expired</h2>' + shot('07-regular-expired','Sales can re-raise an expired approval for a fresh evaluation.') + steps('Open the expired request and select <b>Re-raise request</b>.', 'Review the new result. The app rechecks the eligible previously approved items against current rules and stock evidence, plus arrival timing for Delivery.', 'Proceed only under the new approval. Previously rejected items are not automatically reopened.') + '<h2>What stays visible afterward</h2><p>The request keeps its confirmed action, affected location or TO references, final quantities and completion information. Completed stock evidence is the snapshot for that action; it is not recalculated by subtracting the old request from today’s stock.</p>' + note('Safety stock is a threshold', 'Closing an SO does not itself change the safety-stock requirement. Current availability may change, while the completed request retains its historical evidence. An issued TO is not proof that the physical transfer or delivery has finished.'))

page('pickup-search','Regular · Stocking','SCM opens conversion and adds items','SCM', '''
<p class="lead">Every <b>Stocking</b> request requires SCM review. SCM creates the TO directly; Sales does not enter an SO or confirm an SO-routing popup.</p>
''' + steps('Open the Stocking request and select <b>Convert to TO</b>. The editor contains its actionable items.', 'Adjust each source yard and quantity. Check the calculated transfer quantity in the sales unit.', 'To add stock, type an item code or description in <b>Add an item</b>, then choose a matching autocomplete result. Reject any original request line that should not proceed before conversion.') + shot('08-pickup-autocomplete','SCM changes 2 PLT to 1 PLT + 8 LYR (180 SQFT) and searches for an additional wall-cap item.',645))

page('pickup-quantities','Regular · Stocking','Check final quantities and pallets','SCM', '''
<p>Review every original and added item. Set the <b>PALLET quantity for each TO route</b>; the app calculates a suggestion where conversions are available. Adjust it to the actual load.</p>
''' + shot('09-pickup-editor','The final editor includes the added 10 PC and 2 PALLET for 3445 → 2967. Select Review and convert to TO.',655) + '<p class="small">There is one TO per source yard. Destination remains the request’s Sales yard. Once conversion has started, use its saved retry flow; the issued plan is no longer freely editable.</p>')

page('pickup-confirm','Regular · Stocking','Confirm TO creation and check the result','SCM + Sales', '''
<p>SCM selects <b>Review and convert to TO</b>. The app refreshes the stock evidence and presents a centered confirmation with the routes, quantities, pallets and safety-stock position.</p>
''' + shot('09b-pickup-confirm','Select Confirm and issue TO to create the displayed transfers, or Cancel to return without issuing them.',410) + '<p>Wait for NetSuite. The final request records the adjusted items and TO references so Sales and SCM can read what was done.</p>' + shot('09c-pickup-history','Saved Stocking-conversion result, including final item quantities, route and TO reference.') + note('Follow the same request if a retry is needed', 'The retry continues unfinished work from the saved conversion and preserves completed TOs. Stocking conversion does not use the Sales SO approval-expiry countdown.'))

page('special-header','Special · Sales','Open a special case','Sales', '''
<p class="lead">Use Special for a vendor enquiry with product specifications. A case may contain several items from the same vendor.</p>
''' + steps('Select <b>New Special case</b>. Choose the inquiry store, inquiry date and <b>NetSuite Sales Rep</b>.', 'Enter the customer and vendor. Use directory suggestions when available; an enquiry may begin with a typed name. Check the customer phone and notes.', 'Set the expiry date and choose the fulfillment method. The expiry normally starts one calendar month after the inquiry date.') + shot('10-special-new-header','The case header identifies the enquiry customer, vendor, Sales Rep and expiry.') + table(['Special delivery method','Meaning'],[
 ('Customer pickup at vendor yard','Customer collects directly from the vendor; SCM supplies the pickup location.'),
 ('Pickup at inquired yard','The customer collects at the enquiry’s yard after the stock is arranged there.'),
 ('Delivery','Enter the delivery address and any date, time window and instructions.')]) + note('Enquiry customer versus SO account', 'The original customer remains on the case. At the SO step, select the actual NetSuite billing/customer account; it can be different from the enquiry contact.'))

page('special-items','Special · Sales','Describe, price and submit the items','Sales', steps('Enter product name, colour, size and detailed specification. Make the description specific enough for SCM to check the correct product.', 'Enter quantity, Sales UOM and sales rate per unit. Set a discount if applicable and review the subtotal before tax.', 'Set the required date and any line note or packaging quantities. Use <b>Add line</b> for more items from this vendor.', 'Use <b>Preview quote</b> to check the customer-facing document, then select <b>Submit to SCM</b>. A preview alone does not submit the enquiry.') + shot('11-special-new-item','Item specification, sales pricing, required date and package information.') + '<h2>Pricing example</h2><p><b>2 PLT × $520 × (1 − 5%) = $988 before tax.</b> This is the material subtotal. Pallet charges or delivery charges are added separately at the SO step.</p>' + note('Dates and packaging', 'The application’s delivery rule requires at least <b>three working days after SO creation</b>, excluding weekends and the Ontario holidays in its calendar. A later SO creation date may require a later preferred delivery date. Verify UOM and packaging; 2 PLT and 40 PC may describe the same material quantity.') + '<p class="small">The saved case offers document previews where available. Use the preview dialog’s <b>Download PDF</b> option to save a copy.</p>')

page('special-quote','Special · Sales + SCM','Preview the quote and packing quantities','Sales + SCM', steps('Use <b>Preview quote</b> before submitting, or <b>Preview saved quote</b> on a saved case before SO creation.', 'Check the customer, Sales Rep, item description, sales quantity, rate, discount and total.', 'The packing columns follow the NetSuite sample: <b>PLT · SEC · LYR · PCS</b>. They show entered pallet, section, layer and piece quantities without changing the price calculation.') + shot('11b-special-quote','Example special quote with separate packing columns.',450) + '<p class="small">Use <b>Download PDF</b> to save the preview. Once an SO exists, use its order preview.</p>')

page('special-check','Special · SCM','Record the vendor stock check','SCM', steps('Open the special case in <b>New Enquiry</b> and check each requested item with the vendor.', 'Set its supply status. Confirm the vendor and pickup location. Provide an ETA when the item must wait.', 'Write the customer-facing information in <b>Sales-visible reply</b>. Keep private purchasing notes in <b>SCM internal note</b>.', 'Select <b>Save stock check</b> to publish the responses to Sales.') + shot('12-special-scm-stock','SCM preparing a production-wait response with an ETA and a Sales-visible explanation.') + table(['Supply status','What to record'],[
 ('In stock','Confirm the available product and vendor pickup location.'),
 ('Wait For Production','Enter the expected date and explain the production delay.'),
 ('Wait for Transfer','Enter the expected date and explain the transfer delay.'),
 ('No stock or ETA','Explain the unavailable supply; Sales cannot accept an undated unavailable item.')]) + '<p class="small">The SCM internal note is hidden from Sales. Use the Sales-visible reply for information the customer needs to decide.</p>')

page('special-decision','Special · Sales','Record the customer’s decision','Sales', '''
<p>When the case reaches <b>Await Customer Confirmation</b>, review the vendor response and discuss the product, quantity and timing with the customer.</p>
''' + shot('13-special-customer-decision','The customer accepts the production ETA; the decision and note are saved together.') + steps('For available stock, choose <b>Customer confirms</b>. For dated future stock, choose <b>Customer will wait for ETA</b> only after the customer agrees.', 'If the customer will not proceed, choose the decline option and enter a reason. Add a customer note when useful.', 'Select <b>Save customer decisions</b>. Complete decisions on all lines before creating the SO.', 'Only accepted materials move into the SO draft. Declined items remain on the enquiry record.') + note('Do not treat an ETA as a pickup confirmation', 'Customer acceptance allows the order process to continue. SCM must still confirm actual stock readiness before collection or Dispatch can proceed.') + '<h2>If the vendor changes the answer later</h2><p>A vendor change after PO creation can require Sales to record customer acknowledgement. Read the change, contact the customer and save the acknowledgement on the case. The existing orders and Dispatch arrangement are not silently rewritten by that vendor update.</p>')

page('special-so-account','Special · Sales','Prepare the SO account and fulfillment','Sales', '''
<p class="lead">After customer decisions are complete, use <b>Create or link Sales Order</b> for the accepted materials.</p>
''' + shot('14a-special-so-account','Select the NetSuite account and Sales Rep, then verify the operational yard and delivery information.') + steps('Choose a valid <b>NetSuite customer account</b> from the search suggestions. A typed enquiry name alone is not an SO account selection.', 'Confirm the <b>NetSuite Sales Rep</b> and <b>Operational yard</b>.', 'Check the fulfillment method. For Delivery, verify the address, preferred date, time window, contact information and instructions.', 'Attach delivery photos or video where useful. Then review the material and charge lines on the next page.') + note('Keep the customer’s contact details useful', 'Use a reachable contact and practical delivery instructions. The original enquiry customer stays visible even when the SO uses a separate trade account.'))

page('special-so-create','Special · Sales','Save the draft, then create or link the SO','Sales', shot('14b-special-so-items','Accepted materials, PALLET charges, ancillary items and SO creation/linking actions.') + steps('Check the material description, quantity, fixed original rate, discount and converted NetSuite quantity. Set <b>Pallets needed</b>; 0 omits PALLET. Positive pallet quantity requires its unit price.', 'Use <b>Add ancillary item</b> for delivery charges or other appropriate charges. Select <b>Save SO draft</b>. Any later edit must be saved again.', 'Choose <b>Create in NetSuite</b>, or search for a compatible active SO and use <b>Link existing SO</b>. If a linked estimate is available, the source selector also offers estimate transformation.') + note('Skip buttons are for testing only', 'If <b>Skip SO creation</b> or <b>Skip PO Creation</b> appears, it is a test option. It does not create a real order and does not enter live Dispatch. For a real customer order, use the NetSuite create/link path.', 'warning'))

page('special-po','Special · SCM','Review and create the PO','SCM', steps('Wait until the linked SO is approved/active in NetSuite. Open <b>Review and create Purchase Order</b>.', 'Check description, quantity and UOM. These reviewed values update the SO first; the customer’s Sales prices stay unchanged.', 'Enter <b>unit purchase cost before vendor discount</b> and the vendor discount percentage for every line. Enter <b>0</b> when there is no vendor discount.', 'Select <b>Create PO in NetSuite</b>. If the operation needs attention, use <b>Recover PO operation</b> on the same case.') + shot('15-special-po','PO review uses purchase cost and vendor discount, independently of the customer’s Sales discount.') + '<h2>PO reference / packing slip</h2>' + shot('19-special-po-reference','After PO creation, save the vendor reference when available.') + '<p>The reference is shared with PO Split and the PO/TO Schedule. A blank custom reference uses the PO number.</p>' + note('Sales and vendor discounts are separate', 'The customer’s discount belongs to the SO. The vendor discount belongs to the PO. Review each line’s figures; the resulting order may combine discounts into a single discount line.'))

page('special-readiness','Special · SCM','Check PO approval and stock readiness','SCM', shot('16a-special-po-approval','A created PO still awaiting NetSuite approval keeps the case at Confirmed.',590) + '<p><b>Confirmed does not mean ready for Dispatch.</b> The case waits for confirmed PO approval, then follows the readiness and fulfillment route.</p>' + shot('17-special-readiness','For an accepted waiting item, SCM records Not ready with an ETA, or Ready for collection.',615) + '<p>Use <b>Save stock check</b> after updating readiness. A reminder starts three weekdays before the ETA. Once due, it remains active until SCM explicitly confirms readiness; moving the ETA alone does not clear it.</p>' + note('Check both kinds of status', 'The case stage describes the special-request workflow. <b>Dispatch planning</b> separately shows whether the SO or PO has been assigned to a plan. Read both before promising a collection or delivery.'))

page('special-fulfillment','Special · Fulfillment','Update delivery or complete vendor pickup','Sales + SCM', '''
<p>Sales can update the fulfillment method and delivery details while the case is active and unplanned. Choose the method in the case summary, edit the details and select <b>Save</b>.</p>
''' + shot('18-special-delivery','Delivery summary editor: address, contact, preferred date, time window and instructions.') + note('When editing is locked', 'SO/PO planning or an active/completed handoff can lock these details. Coordinate the change with SCM and Dispatch instead of opening a duplicate case.') + '<h2>Customer pickup at vendor yard</h2><p>After the PO is approved and all accepted items are ready, Sales records the <b>actual pickup date</b> and <b>pickup reference / evidence</b>, then selects <b>Complete vendor pickup</b>.</p>' + shot('22-special-vendor-pickup','Record the real collection, with a traceable reference such as a signed collection receipt.') + '<p>For <b>Pickup at inquired yard</b> and <b>Delivery</b>, follow the Dispatch arrangement and planning status. Creating the SO or PO alone does not mean the customer has received the stock.</p>')

page('special-adjustment','Special · Changes','Request and review an order adjustment','Sales + SCM', steps('Sales opens <b>Request an order adjustment</b>, changes the accepted quantity, discount and/or PALLET quantity, and selects <b>Request adjustment</b>. Original rates stay fixed.', 'SCM reviews the before/after package quantities and the converted SO/PO quantities. Add a review note and choose <b>Confirm adjustment</b> or <b>Reject adjustment</b>.', 'Wait for the update result. Order creation and Dispatch wait for required SCM confirmation. If only part of the update finishes, use <b>Retry order update</b> until both orders are verified.') + shot('20-special-adjustment','Example: 2 → 3 PLT means SO 40 → 60 PC and PO 40 → 60 PC, plus PALLET 2 → 3.') + note('Review material quantity and PALLET separately', 'Product packaging and the chargeable PALLET line are separate values. Check both. A failed or partial remote update stays pending; it is not a reason to issue a second SO or PO.'))

page('special-close','Special · Closure','Close a case and keep the record','Sales + SCM', table(['Case position','Closure path'],[
 ('No issued SO or PO','Enter a close reason and use <b>Close case</b>.'),
 ('SO issued, no PO','Use the available <b>Close SO and case</b> action and provide the reason.'),
 ('PO issued','Sales requests closure; SCM reviews and confirms closure of the SO and PO.'),
 ('Already planned, completed, or blocked by another operation','Resolve the planning/operation state with SCM and Dispatch first. The closure action may be unavailable.')]) + shot('21-special-close','SCM confirms or rejects a requested closure of the linked SO and PO.') + '<p>A closure that has started in NetSuite can require a retry. The case is not marked closed until the required order closures are verified. A closure already being applied cannot simply be rejected halfway through.</p>' + '<h2>Special case expiry</h2><p>The case’s expiry date controls an unissued enquiry. Automatic expiry applies only while <b>no SO or PO exists</b>. Sales can update the expiry where the field is available. This is separate from the regular Pickup / Delivery approval’s short validity window.</p>' + '<h2>Documents and history</h2><p>Use quote or order preview actions where offered, then <b>Download PDF</b>. Check order references, planning status and the audit trail before following up. Sales sees the relevant quote/SO documents; SCM can preview linked SO/PO documents from the case.</p>')

page('statuses','Reference','Read stages, queues and alerts','Sales + SCM', '<h2>Special stages</h2>' + table(['Stage','Meaning / next owner'],[
 ('New Enquiry','SCM checks vendor supply and replies.'),
 ('Await Customer Confirmation','Sales records the customer decisions and prepares the SO.'),
 ('Confirmed','The case is in its order-processing stage. Check SO/PO approval and any pending SCM action.'),
 ('Wait for production / Transfer','Accepted stock is not yet ready; SCM checks ETA and readiness.'),
 ('Dispatch Arrangement','Ready for the relevant Dispatch arrangement; check whether a plan exists.'),
 ('Completed','The operational completion has been recorded.'),
 ('Closed','The enquiry/order path was closed, such as by cancellation, decline or expiry.')]) + '<h2>Alerts</h2>' + table(['Who','What to watch'],[
 ('Sales · Regular','Unread manual approval/rejection decisions. Open the request to read the decision and next action.'),
 ('SCM · Regular','New requests requiring manual review, including every Stocking request.'),
 ('Sales · Special','Own requests at Await Customer Confirmation, Dispatch Arrangement or Wait for production / Transfer.'),
 ('SCM · Special','New enquiries and confirmed cases; also read case-card reminders for readiness, order adjustment and closure.')]) + '<p>Special alert counts reflect workflow stages; they are not simply unread-message counts. A case can remain on an alert list while that stage still applies.</p>' + '<h2>Regular queues and line status</h2><p>Sales uses <b>Pending</b>, <b>Accepted</b> and <b>Completed</b>; SCM also has review, approved, pending-TO, rejected and closed queues. Read individual line decisions and the saved SO/TO action when a request has mixed outcomes.</p>' + note('Queue labels are not delivery receipts', 'An accepted request or created TO may still require physical movement and receiving. Check the transfer, Dispatch or collection result to establish fulfillment.'))

page('troubleshooting','Reference','Resolve common problems','Sales + SCM', table(['What you see','What to do'],[
 ('Pickup or Delivery needs manual review','Read the reason: auto-approval off, stock below safety or missing evidence. Delivery also checks lead time; Pickup has no minimum lead time.'),
 ('A Stocking request did not auto-approve','Expected behavior. SCM must review and convert it directly to TO.'),
 ('SO quantity differs from approval','Compare the item, unit and totals in the error. 912 against 760 approved is 152 too many. Correct the SO or request approval for the intended quantity.'),
 ('SO has PALLET, discount, subtotal or delivery-fee lines','These are accompanying lines, not requested stock. Check the actual material lines to understand the proposed route.'),
 ('SO number is already used','Open its existing regular request. Use a different eligible SO for a separate request.'),
 ('Approval has expired','Use <b>Re-raise request</b> for an unused Pickup or Delivery approval. Recheck the new review result before proceeding.'),
 ('Waiting for NetSuite / buttons disabled','Wait for the operation. If attention or a retry action appears, continue on the same request.'),
 ('SO changed while being checked','Refresh the request, finish any concurrent SO edits, then run <b>Review SO routing</b> again. Read the newly validated action before confirming.'),
 ('Special “Create in NetSuite” is disabled','Select a valid customer account and Sales Rep, complete required fields, and <b>Save SO draft</b>. Resolve any pending SCM quantity review.'),
 ('Special PO cannot be created','Check that the SO is approved and the vendor is valid. Complete purchase costs and each vendor discount field, including 0 when no discount applies.'),
 ('PO exists but the case is still Confirmed','Check the PO approval notice. Dispatch/readiness progression waits for confirmed NetSuite approval.'),
 ('Readiness alert remains after changing ETA','SCM must confirm <b>Ready for collection</b> when the goods are actually ready. A new ETA does not clear a reminder already due.'),
 ('Delivery method or closure is unavailable','Check planning, completion, pending adjustments and any attention message. Coordinate the existing case with SCM/Dispatch.'),
 ('An unfamiliar error persists','Give SCM/support the request reference, SO/PO/TO reference, exact message and action attempted. Preserve the existing request so its saved operation can be checked.')], 'compact') + '<p class="small">Never assume an interrupted browser operation failed to create its order. Check the saved request and references before retrying.</p>')

page('quick-reference','Reference','Daily checklist and terminology','Sales + SCM', '<div class="two-cols"><section><h2>Sales</h2><ul><li>Choose Regular or Special correctly.</li><li>Confirm yard, item, unit, quantity and timing.</li><li>For regular Pickup / Delivery, create the SO at your Sales yard and match the approval.</li><li>Read the routing confirmation before acting.</li><li>For special enquiries, save the customer’s actual decision.</li><li>Check the SO account, selling price, discount, pallets and delivery details.</li><li>Read alerts and the final saved result.</li></ul></section><section><h2>SCM</h2><ul><li>Check the reason for manual review and safety stock on each regular line.</li><li>Finish all required line decisions.</li><li>For Stocking, review edited/added items and PALLET quantities before issuing TOs.</li><li>Review priority replenishment and release it explicitly when appropriate.</li><li>For special cases, confirm vendor, ETA and pickup location.</li><li>Check PO costs/discounts and approval.</li><li>Resolve readiness, adjustment and closure actions.</li></ul></section></div>' + table(['Term','Meaning in this manual'],[
 ('Source yard / destination yard','Where regular requested stock comes from / the Sales yard receiving or requesting it.'),
 ('Safety stock','Minimum stock threshold used to assess the remaining source inventory after shipment.'),
 ('PLT / LYR / SEC / PC or PCS','Pallet / layer / section / piece. Conversion depends on the item.'),
 ('Sales UOM','The sales unit, such as SQFT or EACH, in which approved material quantities are compared.'),
 ('PALLET line','The separate pallet item/charge on an order; it is not a regular requested stock material.'),
 ('Priority replenishment','A regular-request replenishment requirement carried into Smart SCM proposals until released.'),
 ('Revision','The saved version of a request. Refresh if someone else changed it.'),
 ('Attention / recovery','An operation needs review or a retry on the same case before it can finish.')]) + note('Guide scope', 'This edition documents the deployed regular and special stock-request features checked on <b>29 September 2026</b>. Settings and available actions can change. Read the values, reasons and confirmation shown on the actual request.'))

